#[target_feature(enable = "avx512vbmi")]
fn test_x86_avx512vbmi_mm_maskz_multishift_epi64_epi8_vs_unmasked_impl() -> Result<Verdict, String> {
    unsafe {
        let a = create__m128i_from_i32_array([1, 2, 3, 4]);
        let b = create__m128i_from_i32_array([5, 6, 7, 8]);
        let k = create__mmask16_from(0b0101010101010101);
        let masked = unpack__m128i_to_i8_array(_mm_maskz_multishift_epi64_epi8(k, a, b));
        let plain = unpack__m128i_to_i8_array(_mm_multishift_epi64_epi8(a, b));
        let expected: [i8; 16] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { 0 });
        check_array_equality(&masked, &expected).map_err(|e| crate::cpu::with_call(e, "_mm_maskz_multishift_epi64_epi8(k, a, b) vs _mm_multishift_epi64_epi8(a, b)"))?;
        Ok(Verdict::Checked)
    }
}

